package com.jbrempresa.backend.entity;
import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="horarios_recurso",uniqueConstraints=@UniqueConstraint(name="uk_horario_recurso",columnNames={"emp_id","rag_id","hor_dia","hor_ini","hor_fin"})) public class HorarioRecurso{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="hor_id") private Long horId;@Column(name="emp_id",nullable=false)private Long empId;@Column(name="rag_id",nullable=false)private Long ragId;@Column(name="hor_dia",nullable=false)private Integer horDia;@Column(name="hor_ini",nullable=false)private LocalTime horIni;@Column(name="hor_fin",nullable=false)private LocalTime horFin;@Column(name="hor_usu_mov",nullable=false,length=100)private String horUsuMov;@Column(name="hor_fec_mov",nullable=false)private LocalDateTime horFecMov;@Column(name="hor_act",nullable=false)private Boolean horAct;
 public Long getHorId(){return horId;}public void setHorId(Long v){horId=v;}public Long getEmpId(){return empId;}public void setEmpId(Long v){empId=v;}public Long getRagId(){return ragId;}public void setRagId(Long v){ragId=v;}public Integer getHorDia(){return horDia;}public void setHorDia(Integer v){horDia=v;}public LocalTime getHorIni(){return horIni;}public void setHorIni(LocalTime v){horIni=v;}public LocalTime getHorFin(){return horFin;}public void setHorFin(LocalTime v){horFin=v;}public String getHorUsuMov(){return horUsuMov;}public void setHorUsuMov(String v){horUsuMov=v;}public LocalDateTime getHorFecMov(){return horFecMov;}public void setHorFecMov(LocalDateTime v){horFecMov=v;}public Boolean getHorAct(){return horAct;}public void setHorAct(Boolean v){horAct=v;}
}
